import {STAGES,LESSONS} from './curriculum.js';
import {WORD_CONTEXTS} from './contexts.js';
import {createProfile,loadStore,saveStore,validateImport,resetLesson,resetProfile,recordAttempt,statusOf,dueLessons,recommendLesson,chooseWord,buildChoices} from './engine.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byId=new Map(LESSONS.map(l=>[l.id,l]));
const loaded=loadStore();let store=loaded.store,warning=loaded.warning||'',saveBlocked=!!loaded.warning;
let page='home',stage='all',search='',session=null,current=null,viewLesson=null,voices=[],feedback=false,audioUnavailable=false;
const profile=()=>store.profiles.find(p=>p.id===store.activeId)||store.profiles[0];
const statusLabels={new:'Not started',learning:'Learning',practised:'Practised',secure:'Remembered later'};
const status=l=>statusOf(profile(),l.id);
const button=(text,action,cls='secondary',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
function persist(){if(saveBlocked)return;const r=saveStore(store);if(!r.ok){warning=r.error;saveBlocked=true;}showSave();}
function showSave(){$('#save-warning').hidden=!warning;$('#save-warning').textContent=warning;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function refreshHeader(){$('#profile-button').innerHTML=`<span class="avatar">${esc(profile().name[0]?.toUpperCase()||'L')}</span>${esc(profile().name)} <span aria-hidden="true">⌄</span>`;document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===page));showSave();}
function cancelAudio(){if('speechSynthesis'in window)window.speechSynthesis.cancel();}
function speak(text){if(profile().settings.audioEnabled===false){toast('Audio is set to reading partner. Your partner can model the word.');return;}if(!('speechSynthesis'in window)){toast('Word audio is unavailable. Ask a reading partner to say the word.');return;}cancelAudio();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=Number(profile().settings.rate)||.8;const voice=voices.find(v=>v.voiceURI===profile().settings.voice);if(voice){u.voice=voice;u.lang=voice.lang;}u.onerror=e=>{if(e.error!=='interrupted'&&e.error!=='canceled'){audioUnavailable=true;if(current&&session&&!feedback&&['listen','spell'].includes(current.mode)){current.mode='read';renderQuestion();}toast('Device audio is unavailable. Switched to partner-checked reading. Choose a working voice in Settings to restore listening and spelling.');}};window.speechSynthesis.speak(u);}
function loadVoices(){voices='speechSynthesis'in window?window.speechSynthesis.getVoices().filter(v=>v.lang.startsWith('en')):[];}
if('speechSynthesis'in window){loadVoices();window.speechSynthesis.addEventListener('voiceschanged',loadVoices);}
function navigate(target){cancelAudio();session=null;current=null;page=target;history.replaceState(null,'',`#${target}`);refreshHeader();({home:renderHome,map:renderMap,practice:renderPractice,progress:renderProgress,guide:renderGuide,settings:renderSettings}[target]||renderHome)();window.scrollTo(0,0);$('#content').focus({preventScroll:true});}
function heading(k,title,sub=''){return `<div class="page-heading"><span class="eyebrow">${k}</span><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>`;}
function summary(){return {started:LESSONS.filter(l=>status(l)!=='new').length,practised:LESSONS.filter(l=>['practised','secure'].includes(status(l))).length,secure:LESSONS.filter(l=>status(l)==='secure').length,due:dueLessons(profile(),LESSONS).length};}
function card(l){const st=status(l),p=profile().progress[l.id];const progress=st==='secure'?100:st==='practised'?75:Math.min(60,(p?.correct||0)*7);return `<button class="lesson-card" data-action="lesson" data-id="${l.id}"><div class="lesson-card-top"><span class="lesson-number">${l.stage===0?'READY':String(LESSONS.indexOf(l)+1).padStart(2,'0')}</span><span class="lesson-status ${st}">${statusLabels[st]}</span></div><span class="lesson-code">${esc(l.code)}</span><h3 class="lesson-title">${esc(l.title)}</h3><div class="mini-progress"><span style="width:${progress}%"></span></div>${p?`<span class="fine-print">${l.stage===0?(p.oralWords?.length||0)+' spoken checks':(p.independentWords?.length||0)+' / '+l.words.length+' words checked independently'}</span>`:''}<span class="card-arrow" aria-hidden="true">↗</span></button>`;}
function renderHome(){const sum=summary(),next=recommendLesson(profile(),LESSONS)||LESSONS[0],currentStage=STAGES.find(s=>s.id===next.stage);$('#content').innerHTML=`${heading('ONE SOUND AT A TIME',`Hello, ${esc(profile().name)}.`, 'Every word opens a door. Let’s open the next one.')}<section class="hero"><div class="hero-copy"><span class="chip">${sum.started?'YOUR NEXT SMALL STEP':'START YOUR READING JOURNEY'}</span><h2>${sum.started?esc(next.title):'Big readers start<br>with little sounds.'}</h2><p>${sum.started?esc(next.rule):'Learn a sound. Blend a word. Read it for yourself. A clear, careful path from first sounds to unfamiliar words.'}</p><div class="hero-actions">${button(sum.started?'Continue learning →':'Begin the first lesson →','lesson','primary',`data-id="${next.id}"`)}${button('Explore the lessons','map','ghost')}</div><span class="hero-note">${esc(currentStage?.title||'Start here')} · A short lesson + 8 questions</span></div><div class="hero-art" aria-hidden="true"><div class="art-label">little sounds, big possibilities</div><div class="art-tiles"><span class="letter-tile">c</span><span class="letter-tile">a</span><span class="letter-tile">t</span></div><div class="art-blend">⌣ &nbsp; ⌣</div><div class="art-word">cat<span>and just like that, a word.</span></div><span class="art-star">✳</span></div></section><div class="stats"><div class="stat"><span class="stat-number">${sum.practised}<small> / ${LESSONS.length}</small></span><span>Lessons practised</span></div><div class="stat"><span class="stat-number">${sum.secure}</span><span>Remembered on a later day</span></div><div class="stat"><span class="stat-number">${sum.due}</span><span>Lessons ready for review</span></div></div><div class="section-heading"><div><span class="eyebrow">YOUR PATH</span><h2>${esc(currentStage?.title||'First sounds')}</h2></div>${button('View all lessons ↗','map','ghost small')}</div><div class="lesson-grid">${LESSONS.filter(l=>l.stage===next.stage).slice(Math.max(0,LESSONS.filter(l=>l.stage===next.stage).indexOf(next)-1),Math.max(0,LESSONS.filter(l=>l.stage===next.stage).indexOf(next)-1)+3).map(card).join('')}</div><div class="split-grid"><section class="panel"><span class="eyebrow">KEEP IT FRESH</span><h3>A little review goes a long way.</h3><p>Return to words you’re learning. Missed words come back sooner; familiar patterns return over time.</p>${button(sum.due?'Review today’s words →':'Choose your practice →',sum.due?'review':'practice','secondary')}</section><section class="panel"><span class="eyebrow">FOR YOUR READING PARTNER</span><h3>Listen. Model. Encourage.</h3><p>Beginners learn alongside an adult. Say pure sounds, help blend, and check reading aloud. The guide makes it simple.</p>${button('Open the grown-up guide →','guide','ghost')}</section></div>`;}
function renderMap(){const selected=stage==='all'?LESSONS:LESSONS.filter(l=>l.stage===Number(stage)),filtered=selected.filter(l=>(l.title+' '+l.code+' '+l.rule+' '+l.words.join(' ')).toLowerCase().includes(search.toLowerCase()));$('#content').innerHTML=`${heading('THE WHOLE PATH','From first sounds to complex words.',`${LESSONS.length} lessons across ${STAGES.length} stages. Follow the sequence, or open any lesson for targeted practice.`)}<div class="notice">Stages 1–4 build the common code. Later stages extend it to longer words, alternative spellings, and uncommon patterns. Readiness comes first for beginners.</div><label class="search-label">Find a pattern or word<input id="lesson-search" placeholder="Try silent e, ough, or rain" value="${esc(search)}" type="search"></label><div class="stage-tabs" aria-label="Filter lessons"><button data-stage="all" class="${stage==='all'?'active':''}">All stages</button>${STAGES.map(s=>`<button data-stage="${s.id}" class="${String(stage)===String(s.id)?'active':''}">${s.id===0?'Readiness':`Stage ${s.id}`}</button>`).join('')}</div><div id="map-results">${STAGES.filter(s=>filtered.some(l=>l.stage===s.id)).map(s=>`<section class="map-section"><div class="section-heading"><div><span class="eyebrow">${s.id===0?'BEFORE PRINT':`STAGE ${s.id}`}</span><h2>${esc(s.title)}</h2><p>${esc(s.subtitle)}</p></div><span class="badge">${filtered.filter(l=>l.stage===s.id).length} lessons</span></div><div class="lesson-grid">${filtered.filter(l=>l.stage===s.id).map(card).join('')}</div></section>`).join('')||'<div class="empty-state">No matching lessons. Try another word or choose All stages.</div>'}</div>`;}
function lessonView(id){const l=byId.get(id);if(!l)return;cancelAudio();history.replaceState(null,'',`#lesson/${id}`);viewLesson=l;page='map';refreshHeader();const idx=LESSONS.indexOf(l),unmet=idx>0&&!['practised','secure'].includes(status(LESSONS[idx-1]));$('#content').innerHTML=`<div class="lesson-layout"><div class="lesson-heading">${button('← All lessons','map','ghost small')}<span class="badge">${l.stage===0?'Adult-led readiness':`Stage ${l.stage}`} · ${statusLabels[status(l)]}</span></div>${heading(`LESSON ${idx+1}`,esc(l.title),esc(l.code))}${unmet?'<p class="notice">You can practise this now. For a beginner, the earlier lessons provide the sounds used here.</p>':''}<section class="rule-box"><span class="eyebrow">I DO · WATCH AND LISTEN</span><h2>${esc(l.rule)}</h2><p>${esc(l.tip)}</p>${button('♫ Hear the instruction','instruction','ghost small',`data-id="${l.id}"`)}</section><div class="example-grid">${l.examples.map((e,i)=>`<div class="example-card"><span class="segments">${(e.parts?.length?e.parts:[e.word]).map(x=>`<span>${esc(x)}</span>`).join('')}</span><strong>${esc(e.word)}</strong><p>${esc(e.note||'Point to each spelling. Say the sounds, then blend the word.')}</p>${button(WORD_CONTEXTS[e.word.toLowerCase()]?'♫ Hear example sentence':'♫ Hear word','example','ghost small',`data-id="${l.id}" data-index="${i}"`)}</div>`).join('')}</div><section class="panel"><span class="eyebrow">WE DO · TRY TOGETHER</span><ol class="instruction-steps"><li>${l.stage===0?'The adult models the oral task above, without asking the child to read.':'Point to the spellings from left to right. Say the sounds clearly. In a silent-e pattern, the final e has no separate sound; read the vowel and e as a linked pattern.'}</li><li>${l.stage===0?'Let the child try with help. Keep the words spoken, not tested as print.':'Blend without adding an “uh” to consonants. Try the example together.'}</li><li>${l.stage===0?'Try again with another spoken word. Stop when the child needs a break.':'Have the learner say the word alone. Explain its meaning, then use it in a sentence.'}</li></ol>${l.exceptions?`<p class="tip"><strong>Keep in mind:</strong> ${esc(l.exceptions)}</p>`:''}</section><section class="panel"><span class="eyebrow">YOU DO · A SHORT ROUND</span><h3>${l.stage===0?'Try the oral check.':readingOnly(l)?'Read with your partner.':'Read, listen, and spell.'}</h3><p>${l.stage===0?'An adult gives and checks each spoken task. This is readiness practice, not a reading score.':'Eight questions mix the new pattern with a little earlier review. Read-aloud checks need a reading partner; listening choices alone do not prove decoding.'}</p><div class="hero-actions">${button('Start 8 questions →','start','primary',`data-id="${l.id}"`)}${button('Read a sentence','sentence','secondary',`data-id="${l.id}"`)}</div></section><p class="fine-print">Browser audio models whole words. An adult models isolated sounds. American English is the default; valid accent differences are not mistakes.</p></div>`;window.scrollTo(0,0);$('#content').focus({preventScroll:true});}
function renderPractice(){const recommended=recommendLesson(profile(),LESSONS)||LESSONS[0];$('#content').innerHTML=`${heading('A LITTLE MORE PRACTICE','Make the words your own.','Choose any lessons, including ones you haven’t started. Practice can continue for as many short rounds as you want.')}<div class="split-grid"><section class="panel"><h2>Choose your practice</h2><form id="practice-form"><label>Stage<select id="practice-stage"><option value="all">All stages</option>${STAGES.map(s=>`<option value="${s.id}" ${s.id===recommended.stage?'selected':''}>${s.id===0?'Readiness':`Stage ${s.id}`} · ${esc(s.title)}</option>`).join('')}</select></label><label>Lesson<select id="practice-lesson"><option value="all">All lessons in this stage</option>${LESSONS.filter(l=>l.stage===recommended.stage).map(l=>`<option value="${l.id}" ${l.id===recommended.id?'selected':''}>${esc(l.title)}</option>`).join('')}</select></label><label>Practice type<select id="practice-mode"><option value="mixed">Mix reading, listening, and spelling</option><option value="read">Read aloud · partner checks</option><option value="listen">Hear a word → choose its spelling</option><option value="spell">Hear a word → type its spelling</option></select></label><label>Round length<select id="practice-length"><option value="8">8 questions</option><option value="12">12 questions</option><option value="20">20 questions</option></select></label><button class="btn primary" type="submit">Start practice →</button></form></section><section class="panel"><span class="eyebrow">RETRIEVE, THEN REVISIT</span><h2>Keep what you’ve learned.</h2><p>Review selects lessons you have already tried. Your due lessons and missed words get priority.</p>${button('Start a review round →','review','secondary')}<hr><h3>Reading comes first.</h3><p>Listening choices help connect speech to print. To show independent decoding, read words aloud before hearing them, with a partner checking.</p><p>There are no countdowns, lost lives, or penalties for taking a break.</p></section></div>`;}
const homophones=new Set('a I eye aye be bee beat beet blew blue board bored brake break buy by bye cell sell cent scent sent dear deer die dye fair fare feat feet find fined fir fur flea flee flour flower for fore four grate great groan grown hair hare heal heel hear here hi high hole whole hour our idle idol in inn knight night knew new knot not know no made maid mail male main mane meat meet missed mist morning mourning one won pail pale pain pane pair pare pear passed past peace piece plain plane pole poll pray prey principal principle rain reign rein read red right rite write road rode rowed role roll rose rows sail sale sea see seam seem sew so sow sole soul son sun stair stare steal steel suite sweet tail tale tea tee their there they’re threw through throne thrown tide tied to too two toe tow vain vane vein waist waste wait weight ware wear where way weigh weak week weather whether which witch wood would yew you ewe'.toLowerCase().split(' '));
const heteronyms=new Set('read lead wind wound tear bow row bass close live use refuse object present record produce permit conduct project minute desert subject separate content invalid entrance digest polish resume learned blessed crooked aged beloved'.split(' '));
function safeForAudio(word){return !homophones.has(word.toLowerCase())&&!WORD_CONTEXTS[word.toLowerCase()]&&!heteronyms.has(word.toLowerCase())&&!/['’\s-]/.test(word);}
function readingOnly(l){return l.stage!==0&&(l.id==='l116'||audioUnavailable||profile().settings.audioEnabled===false||!('speechSynthesis' in window)||l.words.filter(safeForAudio).length<2);}
function beginSession(pool,mode='mixed',length=8,focus=null){if(!pool.length){toast('Practise a lesson first; review will then bring it back.');return;}cancelAudio();session={pool,mode,length,focus,index:0,correct:0,independent:0,misses:[],recent:[],retry:[],started:Date.now(),items:[]};page='practice';refreshHeader();nextQuestion();}
function startLesson(id){const l=byId.get(id);const earlier=LESSONS.slice(0,LESSONS.indexOf(l)).filter(x=>status(x)!=='new');beginSession([l,...earlier.slice(-4)],'mixed',8,l);}
function nextQuestion(){if(!session)return;if(session.index>=session.length){renderSummary();return;}feedback=false;const retryIndex=session.retry.findIndex(r=>r.at<=session.index);let retry=null;if(retryIndex>=0)retry=session.retry.splice(retryIndex,1)[0];let l=retry?byId.get(retry.id):session.focus&&(session.index%4!==3||session.pool.length===1)?session.focus:session.pool[Math.floor(Math.random()*session.pool.length)];let mode=l.stage===0?'oral':session.mode==='mixed'?['read','listen','spell','read'][session.index%4]:session.mode;
if(l.stage===0)mode='oral';else if(readingOnly(l))mode='read';
let word=retry?.word||chooseWord(profile(),l,{recent:session.recent.map(r=>r.word)});if(mode==='spell'||mode==='listen'){const candidates=l.words.filter(safeForAudio);if(!candidates.length)mode='read';else if(!safeForAudio(word))word=candidates[Math.floor(Math.random()*candidates.length)];}
if((audioUnavailable||profile().settings.audioEnabled===false||!('speechSynthesis'in window))&&(mode==='listen'||mode==='spell'))mode='read';
const variants=WORD_CONTEXTS[word.toLowerCase()];let contextIndex=variants?Math.floor(Math.random()*variants.length):0;if(variants&&l.stage<6){contextIndex=0;if(word.toLowerCase()==='tear'&&/ear, eer/i.test(l.title))contextIndex=1;}
current={l,word,context:variants?.[contextIndex],mode,assisted:!!retry,checked:false,failed:false,revealed:false,answer:'',choices:mode==='listen'?buildChoices(word,l.words.filter(w=>w===word||!homophones.has(w.toLowerCase()))):[],retry:!!retry};session.recent.push({id:l.id,word});session.recent=session.recent.slice(-6);renderQuestion();}
function renderQuestion(){const c=current;if(!c||!session)return;const captions={read:'Read this word aloud.',listen:'Listen. Then choose the word.',spell:'Listen. Then spell the word.',oral:'A spoken task with your grown-up.'};$('#content').innerHTML=`<div class="lesson-layout"><div class="practice-top">${button('← Finish for now','finish','ghost small')}<span class="badge">${esc(c.l.title)}</span><span>${session.index+1} of ${session.length}</span></div><div class="progress-track" aria-label="Round progress"><div class="progress-fill" style="width:${session.index/session.length*100}%"></div></div><section class="practice-card"><span class="question-kicker">${c.retry?'LET’S TRY THAT AGAIN':({read:'READ IT',listen:'FIND IT',spell:'SPELL IT',oral:'SAY IT'}[c.mode])}</span><h2>${captions[c.mode]}</h2>${c.mode==='read'?`${c.context?`<p class="context-sentence">${esc(c.context.sentence)}</p><p class="fine-print">Your partner may read the surrounding sentence. You read the target word for this meaning.</p>`:''}<div class="question-word">${esc(c.word)}</div><p class="question-hint">Say the word before you reveal or hear it.</p>${button('I’ve said it · check →','reveal','primary')}`:c.mode==='oral'?`<div class="oral-prompt"><p><strong>Adult:</strong> ${esc(c.l.rule)}</p><p>${esc(c.l.tip)}</p><p class="target-word">Your spoken example: <strong>${esc(c.word)}</strong></p><p>The adult says the word or its sounds as instructed; the child responds orally. This printed prompt is for the adult.</p></div><label class="check-label"><input type="checkbox" id="adult-check"> I am the adult and checked the response.</label><div class="hero-actions">${button('Correct without help','read-correct','primary')}${button('Needed help · model it','read-help','secondary')}</div>`:`<button class="audio-button" data-action="hear" aria-label="Hear the target word">♫ <span>Hear word</span></button><p class="question-hint">Pattern: ${esc(c.l.code)}</p>${c.mode==='listen'?`<div class="answer-grid">${c.choices.map((w,i)=>`<button class="answer-option" data-action="answer" data-answer="${esc(w)}"><span class="option-key">${i+1}</span>${esc(w)}</button>`).join('')}</div>`:`<form id="spell-form"><label class="sr-only" for="spell-input">Spell the word you heard</label><input id="spell-input" class="word-input" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Type the word" aria-describedby="spell-note"><span id="spell-note" class="fine-print">Use your keyboard, or tap the letters below.</span><div class="keyboard-tiles">${'abcdefghijklmnopqrstuvwxyz'.split('').map(c=>`<button type="button" class="tile" data-action="letter" data-letter="${c}">${c}</button>`).join('')}${button('⌫','backspace','ghost small','type="button" aria-label="Delete last letter"')}</div><button class="btn primary" type="submit">Check spelling →</button></form>`}`}
<div id="question-feedback" aria-live="polite"></div><div class="practice-footer">${button('Show the teaching tip','hint','ghost small')}${button('Skip / show answer','skip','ghost small')}</div></section><p class="fine-print">${c.mode==='spell'?'Spelling practice supports decoding. Homophones and ambiguous forms are checked through reading aloud.':c.mode==='read'?'A reading partner verifies pronunciation. Accept valid dialect variants; words such as read or wind can have more than one correct pronunciation. The microphone is never used.':'Listen as many times as you need. There is no time limit.'}</p></div>`;if(c.mode==='spell')$('#spell-input').focus();window.scrollTo(0,0);}
function reveal(){if(!current||current.revealed||feedback)return;current.revealed=true;const node=$('.practice-card');node.querySelector('[data-action="reveal"]').remove();const el=document.createElement('div');el.className='reading-check';el.innerHTML=`${current.context?`<p class="notice"><strong>Adult guide: ${esc(current.context.pronunciation)}</strong><br>${esc(current.context.meaning)}${current.context.note?' · '+esc(current.context.note):''}</p><p>Check the pronunciation appropriate to the sentence, allowing valid dialect variants. An isolated browser voice is not the answer key for this word.</p>`:button('♫ Hear the word to check','hear','secondary')}<p>Adult: compare the learner’s <em>first</em> attempt with the word. Accept a correct pronunciation in your dialect.</p><label class="check-label"><input type="checkbox" id="adult-check"> I am the reading partner and checked the first attempt.</label><div class="hero-actions">${button('Read correctly','read-correct','primary')}${button('Needed help','read-help','secondary')}</div><p class="fine-print">Practising alone? Leave the box unchecked. It records practice without claiming verified decoding.</p>`;node.insertBefore(el,$('#question-feedback'));}
function grade(correct,adultConfirmed=false){if(!current||feedback||!session)return;feedback=true;const c=current;c.failed=!correct;recordAttempt(profile(),c.l.id,c.word,c.mode,correct,{assisted:c.assisted,adultConfirmed,readingOnly:readingOnly(c.l),requiredWords:c.l.stage>0?c.l.words:undefined});session.index++;if(correct)session.correct++;if(correct&&!c.assisted&&(c.mode==='spell'||(adultConfirmed&&['read','oral'].includes(c.mode))))session.independent++;session.items.push({lesson:c.l.title,word:c.word,correct,mode:c.mode});if(!correct){session.misses.push({id:c.l.id,word:c.word});if(session.index+2<session.length)session.retry.push({id:c.l.id,word:c.word,at:session.index+2});}persist();const msg=correct?(c.assisted?'Good practice with support.':['read','oral'].includes(c.mode)&&!adultConfirmed?'Practice recorded. A partner check is needed for decoding progress.':'Correct. Keep that pattern in mind.'):c.mode==='oral'?'Let’s model the spoken task together.':`The word is “${c.word}”.`;$('#question-feedback').innerHTML=`<div class="feedback ${correct?'correct':'incorrect'}"><h3>${esc(msg)}</h3>${!correct?`<p>${esc(c.l.rule)}</p><p>${c.mode==='oral'?'Adult: model the requested response using this example. Let the child try the same sound task with you.':'Say the word with your partner, then say it once on your own. We’ll revisit it.'}</p>${button('♫ Hear the word','hear','ghost small')}`:''}${button(session.index>=session.length?'See your round →':'Next word →','next','primary')}</div>`;document.querySelectorAll('.answer-option,#spell-form button,#spell-input,[data-action="read-correct"],[data-action="read-help"],[data-action="reveal"],[data-action="skip"],[data-action="hint"]').forEach(el=>el.disabled=true);$('#question-feedback [data-action="next"]').focus();}
function renderSummary(){cancelAudio();if(!session)return;if(!session.summarized&&session.index>0){profile().sessions=(profile().sessions||0)+1;session.summarized=true;persist();}const seen=[...new Set(session.items.map(i=>i.lesson))],main=session.focus||session.pool[0];$('#content').innerHTML=`<div class="lesson-layout session-summary"><div class="summary-emblem" aria-hidden="true">✳</div>${heading('ONE ROUND, ANOTHER STEP','That’s practice worth keeping.',session.index?'You gave these words your attention. Let’s build on that.':'You can return whenever you are ready.')}<div class="stats"><div class="stat"><span class="stat-number">${session.index}</span><span>Words attempted</span></div><div class="stat"><span class="stat-number">${session.independent}</span><span>Independent spelling / checked responses</span></div><div class="stat"><span class="stat-number">${session.misses.length}</span><span>Words to revisit</span></div></div>${session.misses.length?`<section class="panel"><h3>These words will come back.</h3><div class="word-list">${[...new Set(session.misses.map(m=>m.word))].map(w=>`<span class="chip">${esc(w)}</span>`).join('')}</div><p>Read each word with your partner once. A little space before the next try helps.</p></section>`:'<p class="notice success">Keep reading the words in sentences, and come back for a later review.</p>'}<div class="hero-actions">${button('Another round →','again','primary')}${button('Read a sentence','sentence','secondary',`data-id="${main.id}"`)}${button('Take a break','home','ghost')}</div><p class="fine-print">${esc(seen.join(' · '))}</p><p class="fine-print">Progress reflects spelling and adult-checked reading, not just tapping the right answer. “Remembered later” requires a successful delayed reading check.</p></div>`;window.scrollTo(0,0);}
function renderProgress(){const sum=summary();const rows=LESSONS.filter(l=>status(l)!=='new');$('#content').innerHTML=`${heading('WHAT IS TAKING ROOT','Your reading progress.','Reading, spelling, and later recall each tell us something different.')}<div class="stats"><div class="stat"><span class="stat-number">${sum.started}</span><span>Lessons started</span></div><div class="stat"><span class="stat-number">${sum.practised}</span><span>Lessons practised</span></div><div class="stat"><span class="stat-number">${sum.secure}</span><span>Remembered later</span></div></div><section class="panel"><h2>What the labels mean</h2><p><strong>Learning:</strong> you’ve started. <strong>Practised:</strong> every word in the lesson bank has independent evidence, with accurate spelling and checked reading (or broader checked reading when audio spelling is unavailable or ambiguous). <strong>Remembered later:</strong> you also passed a checked reading attempt at least a day after the practice threshold.</p><p>These are transparent practice targets, not a standardized test or a guarantee of mastery. Oral readiness has its own adult-checked target.</p></section>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Lesson</th><th>Progress</th><th>Attempts</th><th>Review</th><th>Reset</th></tr></thead><tbody>${rows.map(l=>{const p=profile().progress[l.id];return `<tr><td><button class="text-link" data-action="lesson" data-id="${l.id}">${esc(l.title)}</button></td><td><span class="badge">${statusLabels[status(l)]}</span></td><td>${p.attempts||0}</td><td>${p.due?new Date(p.due).toLocaleDateString():'Keep practising'}</td><td>${button('Reset','reset-lesson','ghost small',`data-id="${l.id}"`)}</td></tr>`;}).join('')}</tbody></table></div>`:`<div class="empty-state"><h3>Your first step is waiting.</h3><p>Start a lesson to see your progress here.</p>${button('Explore lessons','map','primary')}</div>`}`;}
function renderGuide(){$('#content').innerHTML=`${heading('A GOOD READING PARTNER','Simple teaching. Careful practice.','A practical guide for the adult beside the learner.')}<div class="split-grid"><section class="panel"><h2>1. Teach explicitly</h2><p>Read the rule. Model its examples. Have the learner try with you, then alone. Introduce one small step at a time and follow the early sequence.</p><p>Say consonants cleanly: /m/, not “muh.” Stretch continuous sounds when blending; keep stop sounds brief. Browser voices model whole words, not reliable isolated phonemes.</p><h2>2. Ask for actual reading</h2><p>Let the learner say the printed word before revealing its audio. Check the first response. If you helped, use “Needed help.” Listening choices are useful practice but cannot demonstrate independent decoding.</p><h2>3. Correct and revisit</h2><p>State the correct sound or word, blend it together, then ask for another attempt. The app returns missed words after other questions and schedules later review. Support is recorded separately.</p></section><section class="panel"><h2>4. Take it into text</h2><p>Use each lesson’s sentence after word practice. Help with any explicitly introduced exception words. Ask what the sentence means. Reread it smoothly after decoding; do not use pictures or context to guess at an unread word.</p><p>Read books aloud together too. Vocabulary, oral language, knowledge, and comprehension grow beyond the phonics exercise.</p><h2>5. Keep it inviting</h2><p>Try a short round, then offer a break. Celebrate accurate independent attempts and returning to review. There are no timers, punishments, streak debts, or random prizes.</p><h2>6. Respect dialect</h2><p>The examples generally use American English. Rhoticity, cot/caught, pin/pen, and wh/w vary. A correct local pronunciation is not a decoding error. In Settings, choose an English voice that fits your learner.</p></section></div><section class="panel"><h2>The whole code, and its limits</h2><p>The early core covers productive, common correspondences. Later stages add alternate spellings, syllables, affixes, roots, stress, schwa, silent letters, borrowed spellings, and ambiguous words. English has no finite, exception-free set of rules that determines every word’s pronunciation.</p><p>For an unfamiliar word: inspect its spellings and word parts; try plausible sounds; blend; connect it with a known spoken word and meaning; check a reliable dictionary or knowledgeable speaker when needed. Context can resolve <em>read</em> or <em>wind</em> after decoding their possible forms.</p><h3>Optional transfer checks</h3><p>Some lessons include invented words. They test whether a learner can apply a pattern to a new form. Only an adult supplies and checks their sounds; browser speech must not be used to judge them.</p>${button('Open transfer-word practice','transfer','secondary')}</section><section class="panel"><h2>Why this design?</h2><p>It draws on evidence-supported principles: systematic explicit phonics, linking speech to print, decoding and encoding, connected text, retrieval, and spaced review. The particular app, thresholds, and reward design have not undergone an efficacy trial.</p><ul class="source-list"><li><a href="https://ies.ed.gov/ncee/wwc/PracticeGuide/21" target="_blank" rel="noopener">IES: Foundational Skills to Support Reading</a></li><li><a href="https://ies.ed.gov/ncee/wwc/PracticeGuide/1" target="_blank" rel="noopener">IES: Organizing Instruction and Study</a></li><li><a href="https://www.gov.uk/government/publications/the-reading-framework-teaching-the-foundations-of-literacy" target="_blank" rel="noopener">Department for Education: The Reading Framework</a></li><li><a href="https://www.mentava.com/curriculum" target="_blank" rel="noopener">Mentava’s public curriculum: an example of incremental instruction</a></li></ul><p>All lesson wording and exercises here are original. This project is not affiliated with Mentava, and its promotional results do not validate this app.</p></section>`;}
function renderSettings(){loadVoices();$('#content').innerHTML=`${heading('MAKE IT YOURS','Settings & saves.','Named learner profiles stay separate, without accounts.')}<div class="settings-grid"><section class="panel"><h2>Reading voice</h2><label>Word audio<select id="audio-select"><option value="on" ${profile().settings.audioEnabled!==false?'selected':''}>Device voice</option><option value="off" ${profile().settings.audioEnabled===false?'selected':''}>Reading partner · no device audio</option></select></label><label>English voice<select id="voice-select"><option value="">Device default (American English requested)</option>${voices.map(v=>`<option value="${esc(v.voiceURI)}" ${v.voiceURI===profile().settings.voice?'selected':''}>${esc(v.name)} · ${esc(v.lang)}</option>`).join('')}</select></label><label>Word audio speed<select id="rate-select">${[.65,.8,1].map(r=>`<option value="${r}" ${Number(profile().settings.rate)===r?'selected':''}>${r===.65?'Slow':r===.8?'Steady':'Natural'}</option>`).join('')}</select></label>${button('♫ Test voice','test-voice','secondary')}<p class="fine-print">Word audio depends on your device. Some system voices use a network service. No microphone is recorded or uploaded.</p></section><section class="panel"><h2>Your progress travels with you.</h2><p>Saves belong to this browser and device. Clearing browser data removes them. Export a backup to move profiles to another device or browser.</p><div class="hero-actions">${button('Export all profiles','export','primary')}${button('Import a backup','import','secondary')}</div><input id="import-file" type="file" accept="application/json,.json" hidden><p class="fine-print">Import adds profiles as separate copies. Existing profiles are preserved. No account, IP tracking, advertising, or analytics.</p></section><section class="panel"><h2>Learners</h2><p>Each learner has a separate name, practice history, and audio settings.</p>${button('Manage learner profiles','profiles','secondary')}</section><section class="panel"><h2>Reset progress</h2><p>Reset one lesson or the current learner’s entire progress. Other learners keep their progress. Export a backup first if you may want to restore it.</p><label>Lesson<select id="reset-select">${LESSONS.map(l=>`<option value="${l.id}">${esc(l.title)}</option>`).join('')}</select></label>${button('Reset selected lesson','reset-selected','secondary')}<hr>${button('Reset all progress for this learner','reset-all','danger')}</section></div>`;}
function modal(title,body,actions=''){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}`;if(!d.open)d.showModal();}
function profilesDialog(){modal('Choose a learner',`<div class="profile-list">${store.profiles.map(p=>`<button class="profile-choice ${p.id===profile().id?'active':''}" data-action="switch-profile" data-id="${esc(p.id)}"><span class="avatar">${esc(p.name[0]||'L')}</span><span>${esc(p.name)}</span><span>${p.id===profile().id?'Current':'Choose →'}</span></button>`).join('')}</div><form id="profile-form"><label for="learner-name">Add a learner<input id="learner-name" maxlength="40" placeholder="First name or nickname" required></label><button class="btn primary" type="submit">Create profile</button></form><p class="fine-print">Names are saved on this device. You do not need a password or email.</p>`);}
function sentenceDialog(id){const l=byId.get(id);if(!l)return;modal('Take the words into a sentence.',`<span class="eyebrow">${esc(l.title)}</span>${l.sentences.map((s,i)=>`<div class="sentence"><p>${esc(s)}</p>${button('♫ Hear after reading','hear-sentence','ghost small',`data-id="${l.id}" data-index="${i}"`)}</div>`).join('')}<p>Read it aloud first. Ask: “What happened?” or “What does that mean?” Then reread smoothly. Give help on words beyond the learner’s code knowledge.</p>${l.stage===0?'<p class="notice">An adult reads these sentences; readiness learners are not expected to decode them.</p>':''}`,button('Done','close','primary'));}
function transferDialog(){const list=LESSONS.filter(l=>l.pseudowords?.length);modal('Apply a pattern to a new word.',`<p>These are <strong>invented words</strong>. A reading partner checks the sounds. They are optional transfer checks, not vocabulary or automated scores.</p><label>Choose a pattern<select id="transfer-select">${list.map(l=>`<option value="${l.id}">${esc(l.title)}</option>`).join('')}</select></label><div id="transfer-words"></div>`);renderTransfer(list[0]?.id);}
function renderTransfer(id){const l=byId.get(id);if(!l){$('#transfer-words').innerHTML='<p>No transfer words for this lesson.</p>';return;}$('#transfer-words').innerHTML=l.pseudowords.map(p=>`<div class="example-card"><strong class="transfer-word">${esc(p.word)}</strong><details><summary>Adult pronunciation guide · open after reading</summary><p>${esc(p.guide)}</p></details></div>`).join('');}
function exportData(){const blob=new Blob([JSON.stringify(store,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='phonics-path-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported. Keep it somewhere safe.');}
async function importData(file){try{if(!file)return;if(file.size>2_000_000)throw Error('This backup is too large.');const incoming=validateImport(JSON.parse(await file.text()));if(incoming.profiles.length+store.profiles.length>50)throw Error('Too many profiles. Limit is 50.');for(const p of incoming.profiles){p.id=createProfile(p.name).id;if(store.profiles.some(x=>x.name===p.name))p.name=(p.name+' (imported)').slice(0,40);store.profiles.push(p);}saveBlocked=false;warning='';persist();renderSettings();toast(`Imported ${incoming.profiles.length} learner profile(s). Existing profiles kept.`);}catch(e){toast(`Import failed: ${e.message}`);}}
function requestReset(id){const l=byId.get(id);modal(l?'Reset this lesson?':'Reset this learner’s progress?',`<p>${l?`Reset <strong>${esc(l.title)}</strong> for ${esc(profile().name)}?`:`Reset all lesson progress for <strong>${esc(profile().name)}</strong>?`} This cannot be undone without an exported backup. Other learner profiles are unchanged.</p>`,button('Cancel','close','secondary')+button('Reset progress','confirm-reset','danger',`data-id="${l?.id||'all'}"`));}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return;}const st=e.target.closest('[data-stage]');if(st){stage=st.dataset.stage;renderMap();return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;
if(['home','map','practice','progress','guide','settings'].includes(a)){navigate(a);return;}
if(a==='lesson')lessonView(id);else if(a==='start')startLesson(id);else if(a==='instruction')speak(byId.get(id).rule+' '+byId.get(id).tip);else if(a==='example'){const w=byId.get(id).examples[Number(b.dataset.index)].word;speak(WORD_CONTEXTS[w.toLowerCase()]?.[0]?.sentence||w);}else if(a==='sentence')sentenceDialog(id);else if(a==='hear-sentence')speak(byId.get(id).sentences[Number(b.dataset.index)]);else if(a==='close'){$('#modal').close();cancelAudio();}else if(a==='profiles')profilesDialog();else if(a==='switch-profile'){cancelAudio();store.activeId=id;persist();$('#modal').close();navigate('home');}else if(a==='review'){const due=dueLessons(profile(),LESSONS),pool=due.length?due:LESSONS.filter(l=>status(l)!=='new');beginSession(pool,'mixed',8);}else if(a==='hear'){if(current){if(current.mode==='read'&&!current.revealed)current.assisted=true;speak(current.context?.sentence||current.word);}}else if(a==='reveal')reveal();else if(a==='answer')grade(b.dataset.answer.toLowerCase()===current.word.toLowerCase());else if(a==='read-correct')grade(true,!!$('#adult-check')?.checked);else if(a==='read-help')grade(false,!!$('#adult-check')?.checked);else if(a==='skip')grade(false);else if(a==='hint'){current.assisted=true;modal('Let’s look at the pattern.',`<h3>${esc(current.l.rule)}</h3><p>${esc(current.l.tip)}</p><p>This answer will count as supported practice.</p>`,button('Try with the tip','close','primary'));}else if(a==='next')nextQuestion();else if(a==='finish')renderSummary();else if(a==='again'){beginSession(session.pool,session.mode,session.length,session.focus);}else if(a==='letter'){const i=$('#spell-input');if(i){i.value+=b.dataset.letter;i.focus();}}else if(a==='backspace'){const i=$('#spell-input');i.value=i.value.slice(0,-1);i.focus();}else if(a==='test-voice'){audioUnavailable=false;speak('The cat sat on the mat.');}else if(a==='export')exportData();else if(a==='import')$('#import-file').click();else if(a==='reset-selected')requestReset($('#reset-select').value);else if(a==='reset-lesson')requestReset(id);else if(a==='reset-all')requestReset();else if(a==='confirm-reset'){if(id==='all')resetProfile(profile());else resetLesson(profile(),id);persist();$('#modal').close();navigate('progress');toast('Progress reset.');}else if(a==='transfer')transferDialog();});
document.addEventListener('submit',e=>{if(e.target.id==='spell-form'){e.preventDefault();if(!feedback){const value=$('#spell-input').value.trim().toLowerCase();if(!value){toast('Type the word first, or choose Skip.');return;}grade(value===current.word.toLowerCase());}}else if(e.target.id==='profile-form'){e.preventDefault();const name=$('#learner-name').value.trim();if(!name)return;if(store.profiles.length>=50){toast('This device already has 50 learner profiles.');return;}const p=createProfile(name);store.profiles.push(p);store.activeId=p.id;persist();$('#modal').close();navigate('home');}else if(e.target.id==='practice-form'){e.preventDefault();const st=$('#practice-stage').value,lid=$('#practice-lesson').value,pool=lid==='all'?LESSONS.filter(l=>st==='all'||l.stage===Number(st)):[byId.get(lid)];beginSession(pool,$('#practice-mode').value,Number($('#practice-length').value));}});
document.addEventListener('change',e=>{if(e.target.id==='practice-stage'){const st=e.target.value;$('#practice-lesson').innerHTML='<option value="all">All lessons in this stage</option>'+LESSONS.filter(l=>st==='all'||l.stage===Number(st)).map(l=>`<option value="${l.id}">${esc(l.title)}</option>`).join('');}else if(e.target.id==='voice-select'){profile().settings.voice=e.target.value;audioUnavailable=false;persist();}else if(e.target.id==='audio-select'){profile().settings.audioEnabled=e.target.value==='on';audioUnavailable=false;persist();}else if(e.target.id==='rate-select'){profile().settings.rate=Number(e.target.value);persist();}else if(e.target.id==='import-file')importData(e.target.files[0]);else if(e.target.id==='transfer-select')renderTransfer(e.target.value);});
document.addEventListener('input',e=>{if(e.target.id==='lesson-search'){search=e.target.value;const pos=e.target.selectionStart;renderMap();$('#lesson-search').focus();$('#lesson-search').setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if($('#modal').open||e.target.matches('input,textarea,select'))return;if(current&&!feedback&&current.mode==='listen'&&/^[1-4]$/.test(e.key)){const choice=current.choices[Number(e.key)-1];if(choice){e.preventDefault();grade(choice===current.word);}}});
function route(){const target=location.hash.slice(1);if(target==='content'){$('#content').focus();return;}if(target.startsWith('lesson/')&&byId.has(target.slice(7))){lessonView(target.slice(7));return;}navigate(['home','map','practice','progress','guide','settings'].includes(target)?target:'home');}
window.addEventListener('hashchange',route);
window.addEventListener('pagehide',cancelAudio);
refreshHeader();route();
